(()=>{const signal=document.createElement('div');signal.className='page-load-signal';signal.setAttribute('role','status');signal.textContent='Building the interface…';document.body.append(signal);const finish=()=>{signal.hidden=true};if(document.readyState==='complete')finish();else{document.addEventListener('DOMContentLoaded',()=>{signal.textContent='Assembling page assets…'},{once:true});window.addEventListener('load',finish,{once:true});setTimeout(finish,8000)}window.addEventListener('pageshow',finish);document.addEventListener('click',e=>{const a=e.target.closest?.('a[href]');if(!a||e.defaultPrevented||e.metaKey||e.ctrlKey||a.target||a.download)return;const u=new URL(a.href);if(u.origin===location.origin&&u.pathname!==location.pathname){signal.textContent='Opening page…';signal.hidden=false;setTimeout(finish,8000)}});})();
